/// <summary>
/// Helper class for processing transfer orders from Campbells warehouses.
/// Implements auto-shipment and auto-receipt logic for CSD transfer orders.
/// </summary>
public class METCampbellTransferOrderProcessor
{
    InventTransferTable inventTransferTable;

}

Method.Source:
/// <summary>
/// Construct method to create an instance of the processor
/// </summary>
/// <returns>METCampbellTransferOrderProcessor</returns>
public static METCampbellTransferOrderProcessor construct()
{
    return new METCampbellTransferOrderProcessor();
}

/// <summary>
/// If the transfer order is a CSD, then it should be auto received
/// </summary>
/// <param name = "_transferId">Transfer order number to check if this can be auto-received</param>
/// <returns>Yes if the order should be auto received, otherwise false</returns>
private NoYes shouldAutoReceive(InventTransferId _transferId)
{
    NoYes                       ret = NoYes::No;
    InventTransferTable         trans;
    METInventTransferTableExt   transExt;

    select firstonly TransferType, RecId from transExt
        exists join trans
        where trans.RecId == transExt.InventTransferTable
        && trans.TransferId == _transferId;

    if (transExt.RecId && transExt.TransferType == METCrossDockTransferType::CrossDock)
    {
        ret = NoYes::Yes;

        InventTransferLine      inventTransferLine;
        METInventTransferLine   metInventTransferLine;

        select firstonly RecId from metInventTransferLine
            exists join inventTransferLine
                where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
                    && inventTransferLine.TransferId == _transferId
                    && metInventTransferLine.SalesId == '';

        if (metInventTransferLine)
        {
            ret = checkFailed("@GLS111731");
        }
    }
    else if (transExt.RecId && transExt.TransferType == METCrossDockTransferType::CSD)
    {
        ret = NoYes::Yes;
    }

    return ret;
}

/// <summary>
/// Processes a transfer order picklist for Campbells warehouse logic.
/// If the picklist is for a TO and the "From warehouse" is Campbells, applies special processing:
/// - For CSD TOs: auto ship, auto receive, and consume stock to related SO.
/// - For non-CSD TOs: auto ship only.
/// </summary>
/// <param name="_inventTransferTable">The transfer order table record.</param>
/// <param name="_skipDeliveryReminder">Flag to skip updating delivery reminder</param>
/// <returns>Yes if the order should be auto received, otherwise false</returns>
public boolean processCampbellsTransferOrder(InventTransferTable _inventTransferTable, boolean _skipDeliveryReminder)
{
    boolean ret = true;
    inventTransferTable = _inventTransferTable;

    // 1. Check if picklist is for a TO
    if (!_inventTransferTable)
    {
        return false;
    }

    // 2. Check if "From warehouse" is Campbells
    if (METInventTransferTableExt::isCampbellsWarehouse(_inventTransferTable.InventLocationIdFrom))
    {
        ret = this.autoShipTransferOrder(_inventTransferTable, _skipDeliveryReminder);
    }

    return ret;
}

/// <summary>
/// Automatically ships the transfer order using standard D365 F&O shipment posting.
/// </summary>
/// <param name="_inventTransferTable">The transfer order table record.</param>
/// <param name="_skipDeliveryReminder">Flag to skip updating delivery reminder</param>
/// <returns>Yes if the order should be auto received, otherwise false</returns>
private boolean autoShipTransferOrder(InventTransferTable _inventTransferTable, boolean _skipDeliveryReminder)
{
    InventTransferUpd               invTranUpdShip;
    InventTransferParmTable         inventTransferParmTable;
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    boolean                         ret = true;

    inventTransferParmTable.clear();

    inventTransferParmTable.initParmDefault();

    inventTransferParmTable.ParmId                  = RunBaseMultiParm::getSysParmId();
    inventTransferParmTable.TransferId              = _inventTransferTable.TransferId;
    inventTransferParmTable.UpdateType              = InventTransferUpdateType::Shipment;
    inventTransferParmTable.PrintTransferReceipt    = NoYes::No;

    NoYes autoReceive = this.shouldAutoReceive(_inventTransferTable.TransferId);
    inventTransferParmTable.AutoReceiveQty          = autoReceive; //NoYes::Yes; // Always auto-receive for Campbell's TOs
    inventTransferParmTable.ShipUpdateQty           = InventTransferShipUpdateQty::PickedQty;
    inventTransferParmTable.EditLines               = NoYes::Yes;
    inventTransferParmTable.ExplodeLines            = NoYes::No;
    inventTransferParmTable.TransDate               = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    inventTransferParmTable.insert();

    invTranUpdShip = InventTransferUpdShip::newParmBuffer(inventTransferParmTable);
    invTranUpdShip.run();

    _inventTransferTable.reread();

    if (autoReceive)
    {
        if (_inventTransferTable.TransferStatus == InventTransferStatus::Received)
        {
            info(strFmt("@MET:TOReceived", _inventTransferTable.TransferId));
            ret = METCrossDockSalesFinalizationFacade::construct().process(_inventTransferTable.TransferId, _skipDeliveryReminder);
        }
        else
        {
            ret = false;
        }
    }

    return ret;
}
